const e="ossae-uea-talent-event",d=2023,n="Built from the 2023 circular. The circular prints no entry fee, no street address for the diocese or zonal venues, no phone numbers or emails (the Vice President and Director are named only), no prize list and no marks for Essay or Quiz. The guideline chart prints the diocese event on 30 September 2023 while the text prints the diocese Quiz on 23 September 2023; both are kept (the Quiz date is a Variable). The chart prints one elocution topic for Infants and Sub Juniors and for Juniors, and two for Intermediate and Seniors. The Group Song participant count (3 to 5) is also in the Team row only where it applies to teams.",t={Title:"OSSAE-UEA Talent Event: Rules & Criteria",Subtitle:"Unit, zonal and diocese talent event of the Sunday school association for the UK, Europe and Africa diocese",NoticeTitle:"Please Read Before Registering",Notice:"Head teachers enter their students. All communication from the association office goes to the head teacher only. Participation is more important than winning.",Notes:["Age is calculated as on 1 January {{AgeCutoffYear}}.","Zonal list deadline: {{ZonalListDeadline}}.","Diocese list deadline: {{DioceseListDeadline}}."],Sections:[{Key:"general",Title:"General rules",Items:["The unit, zonal and diocese level events are run fairly, and organisers follow the rules in the circular for the centralised events.","The rules, elocution topics, group song choices and numbers of participants are as printed in the circular. It is the participant's duty to manage time.","Marks are reduced if the allotted time is exceeded or not reached: 0.50 marks for every 30 seconds.","Written manuscripts, electronic devices and visual aids of any kind are not permitted.","Prompting (action or guidance) is not permitted.","Audio or video recording of any kind is not permitted.","Warning bells may be left out to reduce distraction. A stop watch on a projected screen may be used instead.","Sunday school units may also run other co-curricular activities (arts, sports, Bible quiz, Bible reading, essay, story writing, drawing and colouring) for their students."]},{Key:"eligibility",Title:"Who may enter",Items:["Only regular students may take part, at every level.","Students who do not attend regularly, discontinued or disqualified students, and private students (older students who do not fit the age category) are not eligible.","Age groups are fixed by date of birth, as on 1 January {{AgeCutoffYear}}: Infants 1 Jan 2018 to 31 Dec 2018, Sub Juniors 1 Jan 2015 to 31 Dec 2017, Juniors 1 Jan 2012 to 31 Dec 2014, Intermediate 1 Jan 2009 to 31 Dec 2011, Seniors 1 Jan 2004 to 31 Dec 2008.","Head teachers must place each student in the right age group, and this is strictly followed.","Infants (age 4) can take part only in unit level events. Sub Juniors (ages 5 to 7) can go on to the next levels.","Essay Writing is for the Intermediate and Senior groups only, at unit level only.","The Quiz is for the Intermediate and Senior groups only.","Group Song teams have 3 to 5 singers. Two singers are allowed only in exceptional circumstances when a Sunday school has just 2 children in an age group, and the Vicar and Head Teacher must certify this in writing to the Vice President and Director. Never more than 5."]},{Key:"registration",Title:"How to register",Items:["Students enter through their Sunday school unit. The head teacher organises the unit event and sends the winners' details onward.","Head teachers send the list of qualified first and second prize winners of Solo Song, Elocution and Group Song for all categories to the zonal coordinator by email, using the list form (Appendix), on or before midnight of {{ZonalListDeadline}}.","The list gives the unit name, zonal, completion date, the event, the category, the prize, each full name, the date of birth (dd/mm/yyyy) and the signatures of the Vicar and the Head Teacher.","Head teachers send the names of the first and second prize winners of the Intermediate and Senior Quiz at unit level to the zonal coordinators by {{QuizUnitListDeadline}}.","Zonal coordinators send the lists of qualified winners to the Talent Event coordinators, the Sunday school Secretary and the Sunday school Director by midnight of {{DioceseListDeadline}}.","No results or amendments are accepted after the declared deadline."]},{Key:"levels",Title:"Levels and qualification",Items:["There are three levels: unit, zonal and diocese.","Unit events are held on a Saturday or Sunday in February or March ({{UnitEventWindow}}), as suits the unit, with the Vicar (or a priest he authorises) present, in talks with the teachers' council.","Units hold their events early enough for qualified children to prepare for the zonal and diocese events.","First and second prize winners of each category at unit level qualify for the zonal event. First and second prize winners at zonal level qualify for the diocese event.","Zonal events are held on or before {{ZonalEventDate}} in four zones: Ireland, North, Central and South (UK mainland), at venues already chosen ({{ZonalVenues}}). Zonal coordinators tell their units the venue address.","Zonal coordinators run the event with the vicars and head teachers of the venue and may ask the Diocesan Talent Competition Coordinator for advice.","The diocese event is at {{DioceseVenue}}. See the Quiz rule below for the diocese quiz date.","If two persons win first prize and one person is second, the second prize winner does not qualify for the next level.","If more than one person wins second prize, one is chosen by lot to qualify along with the first prize winner.","Quiz: at unit level only the first and second place winners from Intermediate and Senior qualify. At zonal and diocese level these winners join as one team, not as individuals, and represent their parish in their category.","Zonal Quiz is held on {{ZonalQuizDate}}. Zonal winners play the diocese Quiz, held on {{DioceseQuizDate}} between 09:00 and 17:30."]},{Key:"judging",Title:"Judging",Items:["The decision of the judges is final at all levels.","Unit level: a panel of three judges includes at least one from outside the parish. The Vicar may be one of the judges. In special cases judges may come from the same parish, preferably someone whose children are not in that Sunday school, the head teacher tells the zonal coordinator, and one judge must be a priest.","The Vicar, as chairman of the unit, is the final authority for unit judgement and announces winners on the day of the event.","Zonal level: a panel of three judges, preferably from outside the zone. If that is not possible the zonal coordinator asks the Sunday school Director for advice. One judge must be a priest of the church.","Diocese level: the Vice President of the association chooses the judges with the diocesan Metropolitan, tells the Director, and gives clear guidelines to the panel. The Vice President supervises the judging.","Judges use decimal numbers at all three levels so that two or more participants do not get equal scores. Judges sign wherever a correction is made on the score sheet.","The running order is decided by drawing lots. This is strongly advised for Elocution.","Zonal inspectors and diocese officials choose the tabulation team and judges with care, brief them on the rules before each event and remind them to keep results confidential."]},{Key:"conduct",Title:"Conduct",Items:["Taking pictures and publishing pictures of children in the events without permission is not acceptable. Flash photography is strictly restricted at all times.","Parents who want pictures or video of their own children must follow the direction of the organiser.","Supervisors, participants and supporters keep harmony and avoid unhealthy arguments or disputes."]},{Key:"complaints",Title:"Complaints and appeals",Items:["Complaints from an event go to the head teacher of the Sunday school. Disputes are first discussed with the Head Teacher and Vicar.","The Appeal Committee has the Vice President, Director, Secretary, Talent Event Coordinator and, if needed, the Assistant Coordinator.","A participant or parent raises an appeal in writing, signed. The head teacher forwards it only after the parish Vicar approves.","The scanned appeal is emailed to the Director and Secretary within 5 days after the event. Later appeals are not considered under any circumstances.","A decision is made within two weeks and the Director tells the head teacher.","The judges' scores are final and always taken into account. Disqualification appeals follow the yearly talent event guidelines.","The appeal committee's decision is final with no further appeal. It may ask zonal coordinators for the zonal score sheets, which must be supplied in time."]},{Key:"reporting",Title:"Records and reporting",Items:["Head teachers notify the unit event details to their zonal coordinator. After the zonal event, zonal coordinators notify details of first and second prize winners of each category to the Talent Event Coordinator, Sunday school Secretary and Director.","Head teachers and zonal coordinators keep the event details (score sheets, participant lists) for one year. The Diocesan Talent coordinator keeps full diocese event details safely for at least one year."]},{Key:"teams",Title:"Teams",Items:["Group Song has 3 to 5 participants (2 only in exceptional circumstances). One member announces the song reference before singing."]},{Key:"other",Title:"Other items in the circular",Items:["Essay Writing is held on a date chosen by the head teacher with the Vicar and teachers' council, with the Vicar or an authorised priest present. The church provides paper. Mobile and electronic devices are not allowed.","The circular also holds a version history and a participant list form; they are not competition rules."]}],Documents:[{Title:"OSSAE-UEA Talent Event Guidelines 2023 (circular)",Url:"https://stgeorgeorthodox.co.uk/images/downloads/2023/OSSAE-UEA%20TALENT%20EVENT%20GUIDELINE%202023.pdf"}]},o=[],i=[{AgeGroup:"Infants",Source:"Talent Event Guidelines 2023, Infant Category",Sections:{About:null,TimeAndFormat:null,Rules:["Age 4 students. They can take part only in unit level events.","Elocution topic and group song choices are the same as for Sub Juniors: any parable from the Holy Gospels."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Rules
- Age 4 students. They can take part only in unit level events.
- Elocution topic and group song choices are the same as for Sub Juniors: any parable from the Holy Gospels.`},{AgeGroup:"Sub Juniors",Source:"Talent Event Guidelines 2023, Chart",Sections:{About:null,TimeAndFormat:null,Rules:["Elocution topic (one subject only): any parable from the Holy Gospels."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Rules
- Elocution topic (one subject only): any parable from the Holy Gospels.`},{AgeGroup:"Juniors",Source:"Talent Event Guidelines 2023, Chart",Sections:{About:null,TimeAndFormat:null,Rules:["Elocution topic: Importance of prayer in Orthodox life."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Rules
- Elocution topic: Importance of prayer in Orthodox life.`},{AgeGroup:"Intermediate",Source:"Talent Event Guidelines 2023, Chart, Essay, Quiz",Sections:{About:null,TimeAndFormat:null,Rules:["Elocution topics (one is drawn at random): Nicene Creed - core of Orthodox faith; My grace is sufficient for you, 2 Corinthians 12:9.","Essay topic: 1 Peter 3:9 'Not returning evil for evil or insult for insult, but giving a blessing instead'. Include personal, family and church experiences and positive suggestions for spiritual growth. 500 to 750 words, 30 minutes.","Quiz topics: Kukilion 25%, St Matthew 25%, Holy Confession 25%, Church history and tradition (Malankara history from the Synod of Diamper till now) 25%."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Rules
- Elocution topics (one is drawn at random): Nicene Creed - core of Orthodox faith; My grace is sufficient for you, 2 Corinthians 12:9.
- Essay topic: 1 Peter 3:9 'Not returning evil for evil or insult for insult, but giving a blessing instead'. Include personal, family and church experiences and positive suggestions for spiritual growth. 500 to 750 words, 30 minutes.
- Quiz topics: Kukilion 25%, St Matthew 25%, Holy Confession 25%, Church history and tradition (Malankara history from the Synod of Diamper till now) 25%.`},{AgeGroup:"Seniors",Source:"Talent Event Guidelines 2023, Chart, Essay, Quiz",Sections:{About:null,TimeAndFormat:null,Rules:["Elocution topics (one is drawn at random): Why is St Paul called the apostle of the Gentiles?; 'He who eats my flesh and drinks my blood abides in me and I in him', St John 6:56.","Essay topic: 1 Corinthians 2:5 'Your faith should not be in the wisdom of men but in the power of God'. Include background, spiritual message, use in daily life and critical analysis. 750 to 1000 words, 30 minutes.","Quiz topics: Acts of the Apostles 25%, Holy Matrimony 25%, Good Friday Service 25%, Church history and tradition (Malankara history from the Synod of Diamper till now) 25%."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Rules
- Elocution topics (one is drawn at random): Why is St Paul called the apostle of the Gentiles?; 'He who eats my flesh and drinks my blood abides in me and I in him', St John 6:56.
- Essay topic: 1 Corinthians 2:5 'Your faith should not be in the wisdom of men but in the power of God'. Include background, spiritual message, use in daily life and critical analysis. 750 to 1000 words, 30 minutes.
- Quiz topics: Acts of the Apostles 25%, Holy Matrimony 25%, Good Friday Service 25%, Church history and tradition (Malankara history from the Synod of Diamper till now) 25%.`},{AgeGroup:"Infants Group Song",Source:"Talent Event Guidelines 2023, Group Song",Sections:{About:null,TimeAndFormat:null,Rules:["Hymns: any hymn from the MOC Holy Qurbanakramam 2015 and newer editions."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Rules
- Hymns: any hymn from the MOC Holy Qurbanakramam 2015 and newer editions.`},{AgeGroup:"Sub Juniors Group Song",Source:"Talent Event Guidelines 2023, Group Song",Sections:{About:null,TimeAndFormat:null,Rules:["Hymns: any hymn from the MOC Holy Qurbanakramam 2015 and newer editions."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Rules
- Hymns: any hymn from the MOC Holy Qurbanakramam 2015 and newer editions.`},{AgeGroup:"Juniors Group Song",Source:"Talent Event Guidelines 2023, Group Song",Sections:{About:null,TimeAndFormat:null,Rules:["Hymns: any hymn from the MOC Holy Qurbanakramam 2015 and newer editions; Holy Baptism; Eldo; Funeral Service of Men."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Rules
- Hymns: any hymn from the MOC Holy Qurbanakramam 2015 and newer editions; Holy Baptism; Eldo; Funeral Service of Men.`},{AgeGroup:"Intermediate Group Song",Source:"Talent Event Guidelines 2023, Group Song",Sections:{About:null,TimeAndFormat:null,Rules:["Hymns: any hymn from the MOC Holy Qurbanakramam 2015 and newer editions; Perunnal Sushrushakramam (Aandu Taksa); Funeral of Women."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Rules
- Hymns: any hymn from the MOC Holy Qurbanakramam 2015 and newer editions; Perunnal Sushrushakramam (Aandu Taksa); Funeral of Women.`},{AgeGroup:"Seniors Group Song",Source:"Talent Event Guidelines 2023, Group Song",Sections:{About:null,TimeAndFormat:null,Rules:["Hymns: any hymn from the MOC Holy Qurbanakramam 2015 and newer editions; Passion week songs (Passion Monday to Holy Saturday); Shema Namaskaram; Funeral service of priests."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Rules
- Hymns: any hymn from the MOC Holy Qurbanakramam 2015 and newer editions; Passion week songs (Passion Monday to Holy Saturday); Shema Namaskaram; Funeral service of priests.`}],a=[{Title:"Solo Song",Source:"Talent Event Guidelines 2023, Event a",Sections:{About:null,TimeAndFormat:["2 to 3 minutes. No warning bell is given when the time limit is passed."],Rules:["Only Christian devotional songs are allowed. Pop music albums are not allowed.","Language: English or Malayalam.","The same song may be sung in different languages or tones, but different songs must not be mixed."],Allowed:null,NotAllowed:null,Judging:["30 marks: tune 10, rhythm 10, voice 10."],Points:null,Notes:null},Markdown:`## Time and format
- 2 to 3 minutes. No warning bell is given when the time limit is passed.

## Rules
- Only Christian devotional songs are allowed. Pop music albums are not allowed.
- Language: English or Malayalam.
- The same song may be sung in different languages or tones, but different songs must not be mixed.

## Judging
- 30 marks: tune 10, rhythm 10, voice 10.`},{Title:"Elocution",Source:"Talent Event Guidelines 2023, Event c",Sections:{About:null,TimeAndFormat:["3 to 5 minutes. No warning bell is given when the time limit is passed."],Rules:["Where a group has two topics, one is chosen at random before the event starts. Sub Juniors have only one subject.","Language: Malayalam or English only.","Use of any written information, manuscripts or supporting devices is not permitted.","Topics for each age group are in the age group rows."],Allowed:null,NotAllowed:null,Judging:["30 marks: subject and content 10, presentation (ability to convey the message) 10, language 10 (content, language and communication skill)."],Points:null,Notes:null},Markdown:`## Time and format
- 3 to 5 minutes. No warning bell is given when the time limit is passed.

## Rules
- Where a group has two topics, one is chosen at random before the event starts. Sub Juniors have only one subject.
- Language: Malayalam or English only.
- Use of any written information, manuscripts or supporting devices is not permitted.
- Topics for each age group are in the age group rows.

## Judging
- 30 marks: subject and content 10, presentation (ability to convey the message) 10, language 10 (content, language and communication skill).`},{Title:"Group Song",Source:"Talent Event Guidelines 2023, Event b",Sections:{About:null,TimeAndFormat:["2 to 3 minutes. No warning bell is given when the time limit is passed."],Rules:["Hymn choices are limited by age group so small children learn the basic hymns first.","Language: English, Malayalam or Syriac.","One member announces the reference of the song before singing.","The same song may be sung in different languages or tones, but different songs must not be mixed.","Units choose hymns only after talking to their Vicar. If a hymn's validity is unclear, the Vicar and Head Teacher ask the Vice President and Director in writing."],Allowed:null,NotAllowed:null,Judging:["30 marks: tune 10, rhythm 10, harmony 10."],Points:null,Notes:null},Markdown:`## Time and format
- 2 to 3 minutes. No warning bell is given when the time limit is passed.

## Rules
- Hymn choices are limited by age group so small children learn the basic hymns first.
- Language: English, Malayalam or Syriac.
- One member announces the reference of the song before singing.
- The same song may be sung in different languages or tones, but different songs must not be mixed.
- Units choose hymns only after talking to their Vicar. If a hymn's validity is unclear, the Vicar and Head Teacher ask the Vice President and Director in writing.

## Judging
- 30 marks: tune 10, rhythm 10, harmony 10.`},{Title:"Essay Writing",Source:"Talent Event Guidelines 2023, Event d",Sections:{About:null,TimeAndFormat:["30 minutes."],Rules:["New in 2023. Held at unit level only, for Intermediate and Seniors on the same day.","Paper is given by the church. Mobile and electronic devices are not allowed.","The Vicar or a priest he authorises is present at the venue."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:["The circular prints marking guidance but no marks."]},Markdown:`## Time and format
- 30 minutes.

## Rules
- New in 2023. Held at unit level only, for Intermediate and Seniors on the same day.
- Paper is given by the church. Mobile and electronic devices are not allowed.
- The Vicar or a priest he authorises is present at the venue.

## Notes for participants
- The circular prints marking guidance but no marks.`},{Title:"Quiz",Source:"Talent Event Guidelines 2023, Quiz Competition Guideline",Sections:{About:["Aims to improve children's knowledge of the Bible, church history, faith and tradition."],TimeAndFormat:null,Rules:["Held at unit level for Intermediate and Seniors. Unit first and second place winners join as one team at zonal and diocese level.","The decision of the quizmaster is final.","Books, manuscripts, mobile phones and other electronic devices are not allowed."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## About this competition
- Aims to improve children's knowledge of the Bible, church history, faith and tradition.

## Rules
- Held at unit level for Intermediate and Seniors. Unit first and second place winners join as one team at zonal and diocese level.
- The decision of the quizmaster is final.
- Books, manuscripts, mobile phones and other electronic devices are not allowed.`}],s=[],r=[{Key:"AgeCutoffYear",Kind:"text",Label:"Year for age calculation",Value:"2023",Source:"Talent Event Guidelines 2023, Age groups"},{Key:"ZonalListDeadline",Kind:"date",Label:"Last date to send the unit winners' list to the zonal coordinator",Value:"2023-04-30",Source:"Talent Event Guidelines 2023, Zonal Level"},{Key:"QuizUnitListDeadline",Kind:"date",Label:"Last date to send unit Quiz winners' names to zonal coordinators",Value:"2023-04-30",Source:"Talent Event Guidelines 2023, Quiz guideline 3"},{Key:"DioceseListDeadline",Kind:"date",Label:"Last date for zonal coordinators to send the winners' list to the diocese",Value:"2023-07-01",Source:"Talent Event Guidelines 2023, Diocesan Levels"},{Key:"ZonalEventDate",Kind:"date",Label:"Zonal events: on or before",Value:"2023-06-24",Source:"Talent Event Guidelines 2023, Zonal Level"},{Key:"ZonalQuizDate",Kind:"date",Label:"Zonal Quiz date",Value:"2023-06-24",Source:"Talent Event Guidelines 2023, Quiz guideline 2"},{Key:"DioceseQuizDate",Kind:"date",Label:"Diocese Quiz date",Value:"2023-09-23",Source:"Talent Event Guidelines 2023, Diocesan Levels (the guideline chart prints 30 September 2023 for the diocese event)"},{Key:"UnitEventWindow",Kind:"text",Label:"Unit event timing",Value:"a Saturday or Sunday in February or March",Source:"Talent Event Guidelines 2023, Event level"},{Key:"DioceseVenue",Kind:"address",Label:"Diocese event venue",Value:{Name:"Crawley",Address:"",City:"Crawley",MapUrl:"",Directions:"Street address not printed in the circular."},Source:"Talent Event Guidelines 2023, Diocesan Levels"},{Key:"ZonalVenues",Kind:"text",Label:"Zonal venues",Value:"North: Liverpool. Central: Birmingham. South: Canterbury. Ireland: Dublin",Source:"Talent Event Guidelines 2023, Venues"},{Key:"VicePresident",Kind:"contact",Label:"Vice President of the association",Value:{Name:"Rev. Fr. Anoop Malayil Abraham",Role:"Vice President, OSSAE-UK",Phone:"",WhatsApp:"",Email:""},Source:"Talent Event Guidelines 2023, Preface"},{Key:"Director",Kind:"contact",Label:"Director of the association",Value:{Name:"Simon Chacko",Role:"Director, OSSAE-UK",Phone:"",WhatsApp:"",Email:""},Source:"Talent Event Guidelines 2023, Preface"},{Key:"Announcements",Kind:"news",Label:"News printed in the circular",Value:[{Date:"2023-01-11",Title:"Talent Event circular 2023 released",Text:"Circular No. 01/2023 released. Essay Writing is new this year for the Intermediate and Senior groups at unit level.",Url:"https://stgeorgeorthodox.co.uk/images/downloads/2023/OSSAE-UEA%20TALENT%20EVENT%20GUIDELINE%202023.pdf"}],Source:"Talent Event Guidelines 2023, Version History and Essay Writing"}],l=[{Claim:"All rules, dates, levels, appeals and topics are taken from the association's 2023 circular.",SourceType:"Primary - the event's own rules document",Source:"Talent Event Guidelines 2023",Url:"https://stgeorgeorthodox.co.uk/images/downloads/2023/OSSAE-UEA%20TALENT%20EVENT%20GUIDELINE%202023.pdf"},{Claim:"Older editions (UK and Ireland 2016, 2020, 2022) were read for notes only.",SourceType:"Primary - the event's own rules documents (earlier editions)",Source:"Earlier circulars",Url:""}],u={TemplateKey:e,Year:2023,Note:n,Page:t,ParticipantTypes:o,AgeGroups:i,Competitions:a,CompetitionAgeGroups:s,Variables:r,Evidence:l};export{i as AgeGroups,s as CompetitionAgeGroups,a as Competitions,l as Evidence,n as Note,t as Page,o as ParticipantTypes,e as TemplateKey,r as Variables,d as Year,u as default};
